// STEM-azing — invoice request forms (request/*.html, de/request/*.html):
//   estimate(lines, currency)          live starting-price estimate from ticked items
//   estimateText(result, currency, lang) the estimate as display lines
//   pickCurrency(search)               ?currency=USD from the services page, else EUR
// Pages are generated by tools/build-requests.mjs; this file adds the stepper on top.

var money = typeof formatMoney !== "undefined" ? formatMoney : require("./site.js").formatMoney;

var RUSH_RATE = 0.25;   // deadline less than 7 days away
var RUSH_DAYS = 7;

var ESTIMATE_TEXT = {
  en: { total: "Starting estimate: ", from: "From ", plusFrom: "+ from ", quoted: "+ items quoted after review",
        rush: "Rush fee (deadline within 7 days): +25%",
        deposit: "50% deposit books your spot: ", none: "Choose what you need to see a starting estimate.",
        pending: "Enter a quantity to see the price." },
  de: { total: "Erste Preisschätzung: ", from: "Ab ", plusFrom: "+ ab ", quoted: "+ weitere Posten nach Prüfung",
        rush: "Eilzuschlag (Frist unter 7 Tagen): +25 %",
        deposit: "50 % Anzahlung sichert Ihren Termin: ", none: "Wählen Sie aus, was Sie brauchen, um eine erste Preisschätzung zu sehen.",
        pending: "Geben Sie eine Menge ein, um den Preis zu sehen." }
};

// lines: [{ per, eur, usd, qty }], rush: boolean
// → { total, deposit, from: [amounts], quoted, rush: fee, rushed, pending: a priced item still needs its quantity }
function estimate(lines, currency, rush) {
  var r = { total: 0, deposit: 0, from: [], quoted: false, rush: 0, rushed: !!rush, pending: false };
  lines.forEach(function (l) {
    var rate = Number(currency === "USD" ? l.usd : l.eur);
    var qty = Number(l.qty);
    var hasQty = l.qty !== "" && l.qty !== null && isFinite(qty) && qty > 0;
    if (l.per === "session" || l.per === "piece" || l.per === "hour") { if (hasQty) r.total += rate * qty; else r.pending = true; }
    else if (l.per === "1000words") { if (hasQty) r.total += Math.round(rate * qty / 1000); else r.pending = true; }
    else if (l.per === "flat") r.total += rate;
    else if (l.per === "from") r.from.push(rate);
    else if (l.per === "quote") r.quoted = true;
  });
  if (rush) {
    r.rush = Math.round(r.total * RUSH_RATE);
    r.total += r.rush;
    r.from = r.from.map(function (v) { return Math.round(v * (1 + RUSH_RATE)); });
  }
  r.deposit = Math.round(r.total / 2);
  return r;
}

function estimateText(r, currency, lang) {
  var t = ESTIMATE_TEXT[lang] || ESTIMATE_TEXT.en;
  var symbol = currency === "USD" ? "$" : "€";
  var fmt = function (v) { return money(symbol, v, lang); };
  var out = [];
  if (r.total > 0) out.push(t.total + fmt(r.total));
  if (r.total > 0 && r.rushed) out.push(t.rush + " · " + fmt(r.rush));
  r.from.forEach(function (v, i) { out.push((r.total > 0 || i > 0 ? t.plusFrom : t.from) + fmt(v)); });
  if (r.quoted) out.push(t.quoted);
  if (r.total === 0 && r.rushed && out.length) out.push(t.rush);
  if (r.total > 0) out.push(t.deposit + fmt(r.deposit));
  if (out.length) return out;
  return [r.pending ? t.pending : t.none];
}

// Both "YYYY-MM-DD": true when the deadline is today or within the next 6 days.
function isRush(deadline, today) {
  var d = Date.parse(deadline), t = Date.parse(today);
  if (isNaN(d) || isNaN(t)) return false;
  var days = Math.round((d - t) / 86400000);
  return days >= 0 && days < RUSH_DAYS;
}

function pickCurrency(search) {
  var m = /[?&]currency=([^&]*)/i.exec(search || "");
  return m && m[1].toUpperCase() === "USD" ? "USD" : "EUR";
}

if (typeof module !== "undefined") module.exports = { estimate: estimate, estimateText: estimateText, pickCurrency: pickCurrency, isRush: isRush };

(function () {
  "use strict";
  if (typeof document === "undefined") return;
  var form = document.getElementById("request-form");
  if (!form) return;

  var lang = form.getAttribute("data-lang") === "de" ? "de" : "en";
  var MSG = {
    en: { pick: "Please choose at least one option.",
          failed: "Sorry, your request could not be sent. Please try again, or email stemazing.advancement@gmail.com." },
    de: { pick: "Bitte wählen Sie mindestens eine Option.",
          failed: "Ihre Anfrage konnte leider nicht gesendet werden. Bitte versuchen Sie es erneut oder schreiben Sie an stemazing.advancement@gmail.com." }
  }[lang];
  var steps = form.querySelectorAll(".step");
  var marks = form.querySelectorAll(".stepper li");
  var subs = form.querySelectorAll('input[name="sub_services"]');
  var currencySel = form.querySelector('select[name="currency"]');
  var status = form.querySelector(".form-status");
  var current = 0;

  var now = new Date();
  var today = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2);
  var deadline = form.elements.deadline;

  form.noValidate = true;
  form.classList.add("is-stepper");
  currencySel.value = pickCurrency(location.search);
  deadline.min = today;

  // ── Steps ──
  function show(i, focus) {
    current = i;
    steps.forEach(function (s, n) { s.hidden = n !== i; });
    marks.forEach(function (m, n) {
      if (n === i) m.setAttribute("aria-current", "step"); else m.removeAttribute("aria-current");
      m.classList.toggle("is-done", n < i);
    });
    if (focus) {
      var legend = steps[i].querySelector("legend");
      legend.focus();
      legend.scrollIntoView({ block: "start", behavior: "smooth" });
    }
  }

  // Native validation for one step, plus "at least one option" on step 1.
  function stepValid(i) {
    var fields = steps[i].querySelectorAll("input, select, textarea");
    for (var n = 0; n < fields.length; n++) {
      if (!fields[n].checkValidity()) { fields[n].reportValidity(); return false; }
    }
    if (i === 0 && subs.length && ![].some.call(subs, function (c) { return c.checked; })) {
      subs[0].setCustomValidity(MSG.pick);
      subs[0].reportValidity();
      return false;
    }
    return true;
  }
  subs.forEach(function (c) { c.addEventListener("change", function () { subs[0].setCustomValidity(""); }); });

  form.querySelectorAll("[data-step-next]").forEach(function (b) {
    b.addEventListener("click", function () { if (stepValid(current)) show(current + 1, true); });
  });
  form.querySelectorAll("[data-step-prev]").forEach(function (b) {
    b.addEventListener("click", function () { show(current - 1, true); });
  });

  // ── Quantity boxes, "Other" text and hours appear only when they apply ──
  function toggleExtras() {
    form.querySelectorAll(".sub-extra").forEach(function (box) {
      var key = box.getAttribute("data-for");
      var src = key === "hourly" ? form.querySelector('input[name="billing"][value="hourly"]') : form.querySelector('[data-sub="' + key + '"]');
      var on = !!(src && src.checked);
      box.hidden = !on;
      // Disabled fields are neither validated nor sent, so stale extras never block Next or reach the email.
      box.querySelectorAll("input").forEach(function (i) { i.disabled = !on; });
    });
  }

  // ── Live estimate ──
  function lines() {
    var out = [];
    subs.forEach(function (c) {
      if (!c.checked) return;
      var q = form.querySelector('[data-qty-for="' + c.getAttribute("data-sub") + '"]');
      out.push({ per: c.getAttribute("data-per"), eur: c.getAttribute("data-eur"), usd: c.getAttribute("data-usd"), qty: q ? q.value : null });
    });
    var bill = form.querySelector('input[name="billing"]:checked');
    if (bill) {
      var hours = form.querySelector('input[name="hours"]');
      out.push({ per: bill.getAttribute("data-per"), eur: bill.getAttribute("data-eur"), usd: bill.getAttribute("data-usd"), qty: hours ? hours.value : null });
    }
    return out;
  }

  function update() {
    var cur = currencySel.value;
    var text = estimateText(estimate(lines(), cur, isRush(deadline.value, today)), cur, lang);
    var box = form.querySelector("[data-estimate-lines]");
    box.innerHTML = "";
    text.forEach(function (t) { var p = document.createElement("p"); p.textContent = t; box.appendChild(p); });
    form.elements.estimate.value = text.join(" · ");
    var usd = cur === "USD";
    form.querySelectorAll('select[name="budget"] option[data-eur]').forEach(function (o) {
      o.textContent = o.getAttribute(usd ? "data-usd" : "data-eur");
      o.value = o.getAttribute(usd ? "data-val-usd" : "data-val-eur");
    });
    toggleExtras();
  }
  // Enter in a field before the last step means "Next", not "send the whole form".
  form.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" || e.target.tagName !== "INPUT" || current === steps.length - 1) return;
    e.preventDefault();
    if (stepValid(current)) show(current + 1, true);
  });
  form.addEventListener("input", update);
  form.addEventListener("change", update);

  // ── Send through Formspree, staying on the page ──
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    for (var i = 0; i < steps.length; i++) {
      if (!stepValid(i)) { show(i, false); stepValid(i); return; }
    }
    var btn = form.querySelector('button[type="submit"]');
    btn.disabled = true;
    status.hidden = true;
    fetch(form.action, { method: "POST", body: new FormData(form), headers: { Accept: "application/json" } })
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        form.hidden = true;
        var thanks = document.querySelector(".thanks");
        thanks.hidden = false;
        thanks.focus();
      })
      .catch(function () {
        // Clear, show, then fill: screen readers announce the alert again on every failure.
        status.textContent = "";
        status.hidden = false;
        setTimeout(function () { status.textContent = MSG.failed; }, 50);
        btn.disabled = false;
      });
  });

  update();
  show(0, false);
})();
